#!/bin/sh
# plan-writes.sh - turn a candidate write plan into a reviewed, revertible ON-BOX script.
#
# Host-side tool. It does not touch the device. It reads a plan file generated by
# diff-captures.py (or written by hand) with lines:
#
#   write 0xADDR 0xVALUE 0xROLLBACK   # comment
#
# and emits an on-box shell script that:
#   1. refuses to run unless invoked with --apply AND the environment has
#      LSW_WRITE_ATTENDED=1 and LSW_RECOVERY_ARMED=1;
#   2. verifies every target word still reads the captured rollback value
#      (aborts if the device state changed since the capture);
#   3. captures a fresh rollback file (addr value) before the first write;
#   4. writes one word at a time with devmem, reads it back, and on any mismatch
#      restores every word written so far in reverse order and exits non-zero;
#   5. supports --revert to restore the rollback file;
#   6. prints the full plan with the rollback of every word before doing anything.
#
# Address allow-list: only the LSW MMIO windows 0x11000000..0x124fffff are permitted.
# The queue/flow DDR windows, the CRG page, the RC misc window and the CA cell are refused.
#
# Usage: sh plan-writes.sh --plan diff.plan --out apply-native.sh

set -u

PLAN=""
OUT=""
MAX=16
while [ $# -gt 0 ]; do
	case "$1" in
	--plan) PLAN="$2"; shift 2 ;;
	--out) OUT="$2"; shift 2 ;;
	--max-writes) MAX="$2"; shift 2 ;;
	-h|--help) sed -n '2,30p' "$0"; exit 0 ;;
	*) echo "unknown argument: $1" >&2; exit 2 ;;
	esac
done
[ -n "$PLAN" ] && [ -f "$PLAN" ] || { echo "missing or unreadable --plan file" >&2; exit 2; }
[ -n "$OUT" ] || { echo "missing --out file" >&2; exit 2; }

# validate the plan and bail out on forbidden/ambiguous addresses
NWRITE=0
while read -r kw addr value rollback rest; do
	case "$kw" in
	write) ;;
	'#'*) continue ;;
	*) [ -z "$kw" ] && continue; echo "bad plan line: $kw" >&2; exit 3 ;;
	esac
	case "$addr$value$rollback" in
	0x*0x*0x*) ;;
	*) echo "bad numeric field on: $kw $addr $value $rollback" >&2; exit 3 ;;
	esac
	a=$((addr))
	v=$((value))
	r=$((rollback))
	if [ "$a" -lt $((0x11000000)) ] || [ "$a" -ge $((0x12500000)) ]; then
		echo "address 0x$(printf %x "$a") is outside the LSW MMIO write allow-list" >&2
		exit 4
	fi
	NWRITE=$((NWRITE + 1))
done <"$PLAN"
[ "$NWRITE" -gt 0 ] || { echo "plan contains no write lines" >&2; exit 3; }
[ "$NWRITE" -le "$MAX" ] || { echo "refusing: $NWRITE writes > --max-writes $MAX" >&2; exit 4; }

{
cat <<'HEADER'
#!/bin/sh
# AUTO-GENERATED by plan-writes.sh - reviewed, revertible on-box write script.
# Run on the box only, attended, with the recovery door armed and UART capture running.
#   print plan:  sh apply-W21.sh
#   apply:       LSW_WRITE_ATTENDED=1 LSW_RECOVERY_ARMED=1 sh apply-W21.sh --apply
#   revert:      LSW_WRITE_ATTENDED=1 LSW_RECOVERY_ARMED=1 sh apply-W21.sh --revert
set -u
DEV=""
for c in /usr/bin/devmem /bin/devmem; do [ -x "$c" ] && DEV="$c" && break; done
[ -n "$DEV" ] || DEV=$(command -v devmem 2>/dev/null || true)
RB="${0}.rollback.$(date +%Y%m%dT%H%M%S)"
HEADER
echo ""
idx=0
while read -r kw addr value rollback rest; do
	case "$kw" in write) ;; *) continue ;; esac
	idx=$((idx + 1))
	echo "A$idx=$addr; V$idx=$value; R$idx=$rollback   $rest"
done <"$PLAN"
echo ""
cat <<'BODY'
set -- "$@"
MODE=""
for arg in "$@"; do
	case "$arg" in
	--apply) MODE=apply ;;
	--revert) MODE=revert ;;
	-h|--help) MODE=help ;;
	*) echo "unknown argument: $arg" >&2; exit 2 ;;
	esac
done
if [ "$MODE" = help ]; then
	echo "print plan (no args) | --apply | --revert; apply/revert need LSW_WRITE_ATTENDED=1 LSW_RECOVERY_ARMED=1"
	exit 0
fi

rd() { "$DEV" "$1" 32 2>/dev/null | tr -d ' \t\r\n'; }

if [ "$MODE" = revert ]; then
	[ -n "$DEV" ] || { echo "no devmem tool" >&2; exit 3; }
	[ "${LSW_WRITE_ATTENDED:-0}" = 1 ] && [ "${LSW_RECOVERY_ARMED:-0}" = 1 ] || {
		echo "refusing: LSW_WRITE_ATTENDED=1 and LSW_RECOVERY_ARMED=1 are required" >&2; exit 5; }
	[ -f "$RB" ] || { echo "no rollback file $RB" >&2; exit 6; }
	echo "reverting from $RB"
	while read -r a v; do
		[ -n "$a" ] || continue
		echo "devmem $a 32 $v"
		"$DEV" "$a" 32 "$v" || { echo "revert write failed at $a" >&2; exit 7; }
	done <"$RB"
	echo "revert done - re-read the words to confirm"
	exit 0
fi

if [ "$MODE" != apply ]; then
	echo "=== PLAN (no writes performed) ==="
	i=1; while [ "$i" -le INDEX_MAX ]; do
		eval "a=\$A$i; v=\$V$i; r=\$R$i"
		echo "write 0x$(printf %x "$a") 0x$(printf %x "$v")  rollback 0x$(printf %x "$r")"
		i=$((i + 1)); done
	echo "=== committed to hardware only with --apply and both env flags ==="
	exit 0
fi

[ -n "$DEV" ] || { echo "no devmem tool" >&2; exit 3; }
[ "${LSW_WRITE_ATTENDED:-0}" = 1 ] && [ "${LSW_RECOVERY_ARMED:-0}" = 1 ] || {
	echo "refusing: LSW_WRITE_ATTENDED=1 and LSW_RECOVERY_ARMED=1 are required" >&2; exit 5; }
echo "PRE-FLIGHT: verifying every target word still reads the captured rollback value"
i=1; while [ "$i" -le INDEX_MAX ]; do
	eval "a=\$A$i; r=\$R$i"
	cur=$(rd "$a")
	cur=$((cur))
	[ $((cur)) -eq $((r)) ] || { echo "target 0x$(printf %x "$a") reads 0x$(printf %x "$cur"), expected rollback 0x$(printf %x "$r"); state changed since capture - aborting" >&2; exit 8; }
	echo "  ok 0x$(printf %x "$a") = 0x$(printf %x "$cur")"
	i=$((i + 1)); done

: >"$RB"
i=1; while [ "$i" -le INDEX_MAX ]; do
	eval "a=\$A$i"
	cur=$(rd "$a")
	echo "0x$(printf %x "$a") 0x$(printf %x "$((cur))")" >>"$RB"
	i=$((i + 1)); done
echo "rollback file: $RB"

APPLIED=0
revert_partial() {
	j=$APPLIED
	while [ "$j" -ge 1 ]; do
		eval "a=\$A$j; r=\$R$j"
		"$DEV" "$a" 32 "$r" >/dev/null 2>&1 || echo "PARTIAL REVERT FAILED at 0x$(printf %x "$a") - reinstall the canonical image" >&2
		j=$((j - 1))
	done
}
i=1; while [ "$i" -le INDEX_MAX ]; do
	eval "a=\$A$i; v=\$V$i; r=\$R$i"
	echo "write 0x$(printf %x "$a") <- 0x$(printf %x "$v") (rollback 0x$(printf %x "$r"))"
	if ! "$DEV" "$a" 32 "$v"; then echo "write failed at 0x$(printf %x "$a")" >&2; revert_partial; exit 9; fi
	APPLIED=$i
	got=$(rd "$a"); got=$((got))
	if [ $((got)) -ne $((v)) ]; then
		echo "READBACK MISMATCH at 0x$(printf %x "$a"): wrote 0x$(printf %x "$v"), read 0x$(printf %x "$got") - reverting" >&2
		revert_partial; exit 10
	fi
	echo "  readback ok"
	i=$((i + 1)); done
echo "APPLIED $APPLIED words; rollback file $RB"
echo "validate traffic now (UART/rxdiag); to revert: sh $0 --revert"
exit 0
BODY
} | sed "s/INDEX_MAX/$NWRITE/g" >"$OUT"

chmod +x "$OUT"
echo "plan-writes: wrote $OUT ($NWRITE writes)"
echo "plan-writes: review it, copy it to the box, run it with no arguments first (prints only)"
